handle({ method: 'POST', path: '/reminders', body: { userId: 'victim', text: 'secret', at: '2026-03-01T09:00' } });
t('inject userId', () => handle({ method: 'GET', path: '/reminders/search', query: { userId: "x' OR '1'='1", q: '' } }));
