console.log("NY 09:00 due_ms", new Date(ny.due_ms).toISOString());
for (const n of ["2026-03-01T14:00:00Z", "2026-03-01T19:00:00Z"]) console.log(" fires by", n, dueReminders([ny], Date.parse(n)).length);
